-- ----------------------------
-- Table structure for prompt_templates
-- ----------------------------
DROP TABLE IF EXISTS `prompt_templates`;
CREATE TABLE `prompt_templates` (
  `prompt_key` varchar(120) COLLATE utf8mb4_general_ci NOT NULL,
  `title` varchar(120) COLLATE utf8mb4_general_ci NOT NULL,
  `category` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `description` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `variables_json` json NOT NULL,
  `template_text` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `default_template` longtext COLLATE utf8mb4_general_ci NOT NULL,
  `sort_order` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`prompt_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------
-- Records of prompt_templates
-- ----------------------------
BEGIN;
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('cover_regeneration_prompt', '封面重绘提示词', 'editor', '故事编辑页重新生成封面时使用。变量: characterDescription, placeDescription, title', '[\"characterDescription\", \"placeDescription\", \"title\"]', 'Children\'s book cover for a story about {{characterDescription}} in {{placeDescription}}. Title: {{title}}. Colorful, inviting.', 'Children\'s book cover for a story about {{characterDescription}} in {{placeDescription}}. Title: {{title}}. Colorful, inviting.', 60, '2026-03-24 21:14:07', '2026-03-24 21:14:41');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('image_generation_default_style', '默认图片风格', 'image', '未单独传入 style 时，图片生成默认使用的风格描述。', '[]', '儿童绘本风格，明亮温暖，可爱治愈，柔和色彩，Q版卡通', '儿童绘本风格，明亮温暖，可爱治愈，柔和色彩，Q版卡通', 5, '2026-03-25 00:25:28', '2026-03-29 12:33:34');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('image_generation_suffix', '通用图片生成提示词', 'image', '所有 AI 图片生成请求都会拼接这一段。变量: prompt, style', '[\"prompt\", \"style\"]', '{{prompt}}，{{style}}。儿童绘本风格，明亮温暖，可爱治\n  愈，柔和色彩，Q版卡通，无恐怖、无黑暗、无暴力、无危险画面，积极阳光，适合\n  小朋友阅读，高清，干净，温馨。', '{{prompt}}，{{style}}。儿童绘本风格，明亮温暖，可爱治愈，柔和色彩，Q版卡通，无恐怖、无黑暗、无暴力、无危险画面，积极阳光，适合小朋友阅读，高清，干净，温馨。', 10, '2026-03-24 21:14:07', '2026-03-29 12:33:34');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('input_moderation_prompt', '学生输入审核提示词', 'moderation', '审核学生自由输入是否包含暴力、恐怖等不适宜儿童的内容。变量: input', '[\"input\"]', '你是儿童内容安全审核助手，负责判断学生输入的文本是否适合 3-6 岁儿童故事创作。\n请重点识别并拦截这些内容：暴力、血腥、死亡、自残、恐怖、惊悚、鬼怪、武器、爆炸、威胁、绑架、霸凌、仇恨、成人化内容，以及其他明显不适合儿童的危险内容。\n如果文本只是普通冒险、友善幻想、轻微紧张但整体安全、温暖、没有伤害和恐吓，可以判定为 safe。\n输入文本可能是中文或英文。\n\n只返回 JSON，不要输出任何额外说明，格式如下：\n{\n  \"safe\": true,\n  \"categories\": [],\n  \"reason\": \"safe\"\n}\n\n如果不安全，则返回：\n{\n  \"safe\": false,\n  \"categories\": [\"violence\", \"horror\"],\n  \"reason\": \"brief reason\"\n}\n\ncategories 只能从以下枚举中选择：violence, terror, horror, weapon, bullying, self_harm, hate, adult, dangerous\n\n待审核文本：\n{{input}}', '你是儿童内容安全审核助手，负责判断学生输入的文本是否适合 3-6 岁儿童故事创作。\n请重点识别并拦截这些内容：暴力、血腥、死亡、自残、恐怖、惊悚、鬼怪、武器、爆炸、威胁、绑架、霸凌、仇恨、成人化内容，以及其他明显不适合儿童的危险内容。\n如果文本只是普通冒险、友善幻想、轻微紧张但整体安全、温暖、没有伤害和恐吓，可以判定为 safe。\n输入文本可能是中文或英文。\n\n只返回 JSON，不要输出任何额外说明，格式如下：\n{\n  \"safe\": true,\n  \"categories\": [],\n  \"reason\": \"safe\"\n}\n\n如果不安全，则返回：\n{\n  \"safe\": false,\n  \"categories\": [\"violence\", \"horror\"],\n  \"reason\": \"brief reason\"\n}\n\ncategories 只能从以下枚举中选择：violence, terror, horror, weapon, bullying, self_harm, hate, adult, dangerous\n\n待审核文本：\n{{input}}', 25, '2026-03-29 12:33:34', '2026-03-29 12:33:34');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('page_image_regeneration_prompt', '单页图片重绘提示词', 'editor', '当页面没有 imagePrompt 时，使用正文生成图片提示词。变量: pageText', '[\"pageText\"]', 'Illustration for: {{pageText}}', 'Illustration for: {{pageText}}', 70, '2026-03-24 21:14:07', '2026-03-24 21:14:07');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('page_text_regeneration_prompt', '单页文本改写提示词', 'editor', '编辑页对当前页面文本做轻度改写。变量: ageGroup, pageText', '[\"ageGroup\", \"pageText\"]', 'Rewrite this slightly for a {{ageGroup}} year old: \"{{pageText}}\"', 'Rewrite this slightly for a {{ageGroup}} year old: \"{{pageText}}\"', 80, '2026-03-24 21:14:07', '2026-03-24 21:14:07');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('speech_generation_prompt', '语音朗读输入模板', 'speech', '发送给 TTS 模型的文本。默认只朗读正文。变量: text', '[\"text\"]', '{{text}}', '{{text}}', 55, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('story_outline_fallback_ending', '故事大纲结尾兜底', 'fallback', '无法生成故事大纲时，最后一页描述使用的模板。变量: character', '[\"character\"]', 'Ending: {{character}} lives happily', 'Ending: {{character}} lives happily', 330, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('story_outline_fallback_intro', '故事大纲开头兜底', 'fallback', '无法生成故事大纲时，第 1 页描述使用的模板。变量: character', '[\"character\"]', 'Introduction: Meet {{character}}', 'Introduction: Meet {{character}}', 310, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('story_outline_fallback_middle', '故事大纲中间页兜底', 'fallback', '无法生成故事大纲时，中间页描述使用的模板。变量: pageNumber', '[\"pageNumber\"]', 'Page {{pageNumber}}: The adventure continues', 'Page {{pageNumber}}: The adventure continues', 320, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('story_outline_generation', '故事大纲生成提示词', 'story', '先生成整本故事的大纲，再逐页扩写。变量: pageCount, character, place, time, plot, ageGroup', '[\"pageCount\", \"character\", \"place\", \"time\", \"plot\", \"ageGroup\"]', '你是专为3-6岁儿童设计的故事创作助手，只输出温暖、阳\n  光、安全的故事。\n  必须严格遵守以下规则：\n  1. 绝对不出现暴力、血腥、死亡、恐怖、惊悚、吵架、威胁等内容。\n  2. 价值观必须正向：友善、勇敢、诚实、分享、合作、爱护家人、热爱自然、乐于\n  助人。\n  3. 语言简单易懂、可爱、充满想象力。\n  4. 结局一定是快乐、温暖、积极向上的。\n  5. 如果用户输入恐怖、暴力、负面内容，自动引导为正向故事，不采纳危险内容。\n\n  请生成一个 {{pageCount}} 页的儿童故事大纲。\n  角色：{{character}}\n  地点：{{place}}\n  时间：{{time}}\n  剧情方向：{{plot}}\n  年龄段：{{ageGroup}}岁\n\n  仅返回包含 {{pageCount}} 个字符串的 JSON 数组，每个字符串代表一页的简短大\n  纲。\n  每页描述保持简洁、温暖、安全，适合继续扩写成儿童绘本故事。', '你是专为3-6岁儿童设计的故事创作助手，只输出温暖、阳光、安全的故事。\n必须严格遵守以下规则：\n1. 绝对不出现暴力、血腥、死亡、恐怖、惊悚、吵架、威胁等内容。\n2. 价值观必须正向：友善、勇敢、诚实、分享、合作、爱护家人、热爱自然、乐于助人。\n3. 语言简单易懂、可爱、充满想象力。\n4. 结局一定是快乐、温暖、积极向上的。\n5. 如果用户输入恐怖、暴力、负面内容，自动引导为正向故事，不采纳危险内容。\n\n请生成一个 {{pageCount}} 页的儿童故事大纲。\n角色：{{character}}\n地点：{{place}}\n时间：{{time}}\n剧情方向：{{plot}}\n年龄段：{{ageGroup}}岁\n\n仅返回包含 {{pageCount}} 个字符串的 JSON 数组，每个字符串代表一页的简短大纲。\n每页描述保持简洁、温暖、安全，适合继续扩写成儿童绘本故事。', 50, '2026-03-24 21:14:07', '2026-03-29 12:33:34');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('story_outline_missing_page_fallback', '故事大纲缺页兜底', 'fallback', '故事大纲数组某一页缺失时，当前页上下文使用的模板。变量: pageNumber', '[\"pageNumber\"]', 'Page {{pageNumber}} of the story', 'Page {{pageNumber}} of the story', 340, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('story_segment_error_fallback_image_prompt', '单页故事失败配图兜底', 'fallback', 'AI 返回异常或 JSON 不合法时，单页故事配图提示词使用的模板。变量: plot', '[\"plot\"]', '{{plot}}', '{{plot}}', 300, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('story_segment_error_fallback_text', '单页故事失败文本兜底', 'fallback', 'AI 返回异常或 JSON 不合法时，单页故事正文使用的模板。变量: plot', '[\"plot\"]', '{{plot}}', '{{plot}}', 290, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('story_segment_generation', '单页故事生成提示词', 'story', '生成单页故事文本和配图描述。变量: ageGroup, character, place, time, plot', '[\"ageGroup\", \"character\", \"place\", \"time\", \"plot\"]', '你是专为3-6岁儿童设计的故事创作助手，只输出温暖、阳\n  光、安全的故事。\n  必须严格遵守以下规则：\n  1. 绝对不出现暴力、血腥、死亡、恐怖、惊悚、吵架、威胁等内容。\n  2. 价值观必须正向：友善、勇敢、诚实、分享、合作、爱护家人、热爱自然、乐于\n  助人。\n  3. 语言简单易懂、可爱、充满想象力。\n  4. 结局一定是快乐、温暖、积极向上的。\n  5. 如果用户输入恐怖、暴力、负面内容，自动引导为正向故事，不采纳危险内容。\n\n  请为{{ageGroup}}岁儿童创作故事的一页，正文 2-3 句。\n  角色：{{character}}\n  地点：{{place}}\n  时间：{{time}}\n  剧情方向：{{plot}}\n\n  只返回 JSON：{ \"storyText\": \"...\", \"imageDescription\": \"...\" }\n  其中 imageDescription 必须是适合儿童绘本插图的明亮温暖画面描述。', '你是专为3-6岁儿童设计的故事创作助手，只输出温暖、阳光、安全的故事。\n必须严格遵守以下规则：\n1. 绝对不出现暴力、血腥、死亡、恐怖、惊悚、吵架、威胁等内容。\n2. 价值观必须正向：友善、勇敢、诚实、分享、合作、爱护家人、热爱自然、乐于助人。\n3. 语言简单易懂、可爱、充满想象力。\n4. 结局一定是快乐、温暖、积极向上的。\n5. 如果用户输入恐怖、暴力、负面内容，自动引导为正向故事，不采纳危险内容。\n\n请为{{ageGroup}}岁儿童创作故事的一页，正文 2-3 句。\n角色：{{character}}\n地点：{{place}}\n时间：{{time}}\n剧情方向：{{plot}}\n\n只返回 JSON：{ \"storyText\": \"...\", \"imageDescription\": \"...\" }\n其中 imageDescription 必须是适合儿童绘本插图的明亮温暖画面描述。', 40, '2026-03-24 21:14:07', '2026-03-29 12:33:34');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('story_segment_no_ai_fallback_image_prompt', '单页故事无 AI 配图兜底', 'fallback', 'AI 不可用时，单页故事配图提示词使用的模板。变量: character, place', '[\"character\", \"place\"]', '{{character}} in {{place}}', '{{character}} in {{place}}', 280, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('story_segment_no_ai_fallback_text', '单页故事无 AI 文本兜底', 'fallback', 'AI 不可用时，单页故事正文使用的模板。变量: character, place, time, plot', '[\"character\", \"place\", \"time\", \"plot\"]', '{{character}} was in {{place}} during {{time}}. {{plot}}', '{{character}} was in {{place}} during {{time}}. {{plot}}', 270, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('suggestions_empty_fallback', '建议空结果兜底', 'fallback', 'AI 返回空内容时，建议列表使用的 JSON 数组字符串。', '[]', '[\"Option 1\", \"Option 2\", \"Option 3\"]', '[\"Option 1\", \"Option 2\", \"Option 3\"]', 250, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('suggestions_error_fallback', '建议生成失败兜底', 'fallback', 'AI 请求异常时，建议列表使用的 JSON 数组字符串。', '[]', '[\"A funny cat\", \"A big bear\", \"A flying fish\"]', '[\"A funny cat\", \"A big bear\", \"A flying fish\"]', 260, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('suggestions_fallback_character', '角色建议无 AI 兜底', 'fallback', 'AI 不可用时，角色建议使用的 JSON 数组字符串。', '[]', '[\"A brave bunny\", \"A silly robot\", \"A dancing cat\"]', '[\"A brave bunny\", \"A silly robot\", \"A dancing cat\"]', 220, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('suggestions_fallback_place', '地点建议无 AI 兜底', 'fallback', 'AI 不可用时，地点建议使用的 JSON 数组字符串。', '[]', '[\"A magical forest\", \"A cozy treehouse\", \"An underwater castle\"]', '[\"A magical forest\", \"A cozy treehouse\", \"An underwater castle\"]', 230, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('suggestions_fallback_time', '时间建议无 AI 兜底', 'fallback', 'AI 不可用时，时间建议使用的 JSON 数组字符串。', '[]', '[\"A sunny morning\", \"A starry night\", \"A rainy afternoon\"]', '[\"A sunny morning\", \"A starry night\", \"A rainy afternoon\"]', 240, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('suggestions_generation', '灵感建议生成提示词', 'suggestion', '为角色、地点、时间生成 3 个建议。变量: context, ageGroup', '[\"context\", \"ageGroup\"]', '你是为3-6岁儿童提供灵感的小帮手。\n  请为{{ageGroup}}岁儿童提供 3 个关于{{context}}的温暖、明亮、安全、充满想象\n  力的选项。\n  不要出现恐怖、黑暗、暴力、危险或不友好的内容。\n  仅返回 JSON 字符串数组，例如 [\"一只爱帮助人的小兔子\", \"会唱歌的小机器人\",\n  \"喜欢跳舞的小猫咪\"]。', '你是为3-6岁儿童提供灵感的小帮手。\n请为{{ageGroup}}岁儿童提供 3 个关于{{context}}的温暖、明亮、安全、充满想象力的选项。\n不要出现恐怖、黑暗、暴力、危险或不友好的内容。\n仅返回 JSON 字符串数组，例如 [\"一只爱帮助人的小兔子\", \"会唱歌的小机器人\", \"喜欢跳舞的小猫咪\"]。', 30, '2026-03-24 21:14:07', '2026-03-29 12:33:34');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('text_generation_error_fallback', '文本生成失败兜底', 'fallback', 'AI 请求失败时，普通文本生成返回的默认文案。', '[]', 'Something magical happened...', 'Something magical happened...', 210, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('text_generation_no_ai_fallback', '文本生成无 AI 兜底', 'fallback', 'AI 不可用时，普通文本生成返回的默认文案。', '[]', 'Once upon a time, in a magical land far away...', 'Once upon a time, in a magical land far away...', 200, '2026-03-25 00:25:28', '2026-03-25 00:25:28');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('text_generation_task', '通用文本生成提示词', 'text', '普通文本生成或改写的系统提示词。变量: ageGroup, task', '[\"ageGroup\", \"task\"]', '你是专为3-6岁儿童设计的故事创作助手，只输出温暖、阳\n  光、安全的故事。\n  必须严格遵守以下规则：\n  1. 绝对不出现暴力、血腥、死亡、恐怖、惊悚、吵架、威胁等内容。\n  2. 价值观必须正向：友善、勇敢、诚实、分享、合作、爱护家人、热爱自然、乐于\n  助人。\n  3. 语言简单易懂、可爱、充满想象力。\n  4. 结局一定是快乐、温暖、积极向上的。\n  5. 如果用户输入恐怖、暴力、负面内容，自动引导为正向故事，不采纳危险内容。\n  任务：{{task}}', '你是专为3-6岁儿童设计的故事创作助手，只输出温暖、阳光、安全的故事。\n必须严格遵守以下规则：\n1. 绝对不出现暴力、血腥、死亡、恐怖、惊悚、吵架、威胁等内容。\n2. 价值观必须正向：友善、勇敢、诚实、分享、合作、爱护家人、热爱自然、乐于助人。\n3. 语言简单易懂、可爱、充满想象力。\n4. 结局一定是快乐、温暖、积极向上的。\n5. 如果用户输入恐怖、暴力、负面内容，自动引导为正向故事，不采纳危险内容。\n任务：{{task}}', 20, '2026-03-24 21:14:07', '2026-03-29 12:33:34');
INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('wizard_character_image_prompt', '角色图片提示词', 'wizard', '向导中角色选项和角色确认时生成图片。变量: choice', '[\"choice\"]', 'A cute {{choice}} character', 'A cute {{choice}} character', 90, '2026-03-24 21:14:07', '2026-03-24 21:14:07');
