INSERT INTO `prompt_templates` (`prompt_key`, `title`, `category`, `description`, `variables_json`, `template_text`, `default_template`, `sort_order`, `created_at`, `updated_at`) VALUES ('wizard_time_image_prompt', '时间图片提示词', 'wizard', '向导中时间选项和时间确认时生成图片。变量: choice', '[\"choice\"]', 'A cartoon scene of {{choice}}, children\'s book style', 'A cartoon scene of {{choice}}, children\'s book style', 110, '2026-03-24 21:14:07', '2026-03-24 21:14:07');
