-- ----------------------------
-- Table structure for qr_login_tokens
-- ----------------------------
DROP TABLE IF EXISTS `qr_login_tokens`;
CREATE TABLE `qr_login_tokens` (
  `id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `account_id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `entity_type` enum('school_admin','teacher','student') COLLATE utf8mb4_general_ci NOT NULL,
  `entity_id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `token` text COLLATE utf8mb4_general_ci NOT NULL,
  `status` enum('active','used','expired','revoked') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active',
  `expires_at` datetime NOT NULL,
  `used_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_qr_account_status` (`account_id`,`status`),
  CONSTRAINT `fk_qr_account` FOREIGN KEY (`account_id`) REFERENCES `accounts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------
-- Records of qr_login_tokens
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for schools
-- ----------------------------
DROP TABLE IF EXISTS `schools`;
CREATE TABLE `schools` (
  `id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `name` varchar(120) COLLATE utf8mb4_general_ci NOT NULL,
  `code` varchar(32) COLLATE utf8mb4_general_ci NOT NULL,
  `address` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `contact_name` varchar(64) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `contact_phone` varchar(32) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` enum('active','disabled') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------
-- Records of schools
-- ----------------------------
BEGIN;
INSERT INTO `schools` (`id`, `name`, `code`, `address`, `contact_name`, `contact_phone`, `status`, `created_at`, `updated_at`) VALUES ('d7c23cbd-39ed-4edf-be16-b9af37327649', '11', '11', '1', '1', '1', 'active', '2026-03-24 20:35:03', '2026-03-24 20:35:03');
