COMMIT;

-- ----------------------------
-- Table structure for stories
-- ----------------------------
DROP TABLE IF EXISTS `stories`;
CREATE TABLE `stories` (
  `id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `school_id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `class_id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `teacher_id` char(36) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `student_id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `cover_image` text COLLATE utf8mb4_general_ci,
  `author_id` char(36) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `author_name` varchar(120) COLLATE utf8mb4_general_ci NOT NULL,
  `age_group` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `character_payload` json NOT NULL,
  `place_payload` json NOT NULL,
  `time_label` varchar(120) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pages_payload` json NOT NULL,
  `styling_payload` json NOT NULL,
  `status` enum('draft','published','archived') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'published',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_story_school` (`school_id`),
  KEY `idx_story_class` (`class_id`),
  KEY `idx_story_teacher` (`teacher_id`),
  KEY `idx_story_student` (`student_id`),
  CONSTRAINT `fk_stories_class` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_stories_school` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_stories_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_stories_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `teachers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------
-- Records of stories
-- ----------------------------
BEGIN;
INSERT INTO `stories` (`id`, `school_id`, `class_id`, `teacher_id`, `student_id`, `title`, `cover_image`, `author_id`, `author_name`, `age_group`, `character_payload`, `place_payload`, `time_label`, `pages_payload`, `styling_payload`, `status`, `created_at`, `updated_at`) VALUES ('4a8f4b4a-eda4-40c2-8906-bbfb82746ab4', 'ec359f0d-77a6-40ea-b777-0dcd76b255d9', '5f73c7dd-0467-4e1b-a659-d5f180d66657', 'cfad9c1c-03ba-4f42-b6d3-772d11de7425', '871d184a-58a1-4f07-b344-a2c79efc0a94', '一个勇敢机器人\'s Adventure---', '', '871d184a-58a1-4f07-b344-a2c79efc0a94', 'Mia', '3-5', '{\"name\": \"一个勇敢机器人\", \"imageUrl\": \"data:image/png;base64,\", \"description\": \"一个勇敢机器人\"}', '{\"name\": \"在火星上面\", \"imageUrl\": \"data:image/png;base64,\", \"description\": \"在火星上面\"}', '在位俩', '[{\"text\": \"很久很久以前，在红色的火星上，住着一个名叫小勇的勇敢机器人。他有着闪亮的金属身体和两只发出柔和光芒的眼睛，每天都开心地在红色的沙丘上探险。有一天，小勇看到一个小小的、亮晶晶的东西在沙子里闪烁，那是一颗迷路的火星宝石！勇敢的小勇知道，他必须小心翼翼地把宝石捡起来，送回它妈妈身边去。\", \"imageUrl\": \"data:image/png;base64,\", \"imagePrompt\": \"一个勇敢友好的机器人小勇，有着闪亮的银色身体和发光的眼睛，正在红色的火星上探索。他弯下腰，小心翼翼地从红色的沙丘中捡起一颗闪闪发光的彩色宝石。背景是橙色的天空和远处的红色山脉。\"}, {\"text\": \"在一个亮晶晶的火星夜晚，勇敢的小勇机器人正在巡逻。突然，他听到\'呜呜\'的微弱哭声，听起来像一个小宝宝！小勇沿着声音走过去，发现一个迷路的小火星宝宝正坐在红色的沙地上哭鼻子呢。\", \"imageUrl\": \"data:image/png;base64,\", \"imagePrompt\": \"A friendly, brave robot with big eyes, named Xiao Yong, standing on a bright red Mars landscape at night. He is looking down at a very small, cute green Martian baby with big eyes, who is sitting on the red ground and crying softly. Twinkling stars are visible in the dark sky above.\"}, {\"text\": \"晚上，在红红的火星上，勇敢的小勇机器人看到一个小火星宝宝坐在石头后面，它哭得很伤心。小勇机器人跑过去，温柔地问：“小火星宝宝，你为什么哭呢？”小宝宝抽抽噎噎地说：“我找不到我的妈妈了！” 小勇拍拍胸脯说：“别怕！勇敢的小勇一定会帮你找到妈妈的！”\", \"imageUrl\": \"data:image/png;base64,\", \"imagePrompt\": \"A brave and friendly robot, \'Xiao Yong\', with big, kind eyes and a sturdy body, stands on a red, rocky Mars landscape. Next to the robot is a small, green Martian baby with teary eyes, looking sad. The sky is dark with a few twinkling stars, showing it\'s evening. The robot is looking at the Martian baby with a comforting expression, ready to help.\"}, {\"text\": \"在红色的火星上，小勇机器人一大早就醒来了。他勇敢地爬过一个个小山坡，又灵活地跳过闪亮的小石块。小勇仔细地跟着一串串脚印，一步一步，要去找到他的火星妈妈。\", \"imageUrl\": \"data:image/png;base64,\", \"imagePrompt\": \"A cute, friendly, brave little robot named Xiao Yong, with a shiny red body and big, curious eyes, exploring the surface of Mars. The landscape is a vibrant red-orange with gentle, rolling hills and sparkling small rocks. Xiao Yong is bending slightly, looking down and following a trail of footprints across the dusty ground. The sky is a soft, light blue and pink, indicating early morning on Mars.\"}, {\"text\": \"勇敢的小机器人小勇，在红色的火星上努力寻找着。终于，在一个小小的山洞里，他看到了火星宝宝和火星妈妈！火星宝宝开心地扑进妈妈的怀抱，紧紧抱在一起，小勇真是个超级棒的机器人！\", \"imageUrl\": \"data:image/png;base64,\", \"imagePrompt\": \"A brave and friendly robot named Xiaoyong stands proudly on the red, rocky surface of Mars. In front of him, a small, cute Martian baby with big eyes is happily hugging its larger Martian mother. The scene is full of warmth and joy, under a beautiful Martian sky, highlighting their reunion.\"}]', '{\"fontFamily\": \"font-comic\", \"titleColor\": \"#7209B7\"}', 'published', '2026-03-24 23:15:14', '2026-03-25 00:35:16');
INSERT INTO `stories` (`id`, `school_id`, `class_id`, `teacher_id`, `student_id`, `title`, `cover_image`, `author_id`, `author_name`, `age_group`, `character_payload`, `place_payload`, `time_label`, `pages_payload`, `styling_payload`, `status`, `created_at`, `updated_at`) VALUES ('68f78ab2-1a51-43b2-a7ba-75c3681f31a6', 'ec359f0d-77a6-40ea-b777-0dcd76b255d9', '5f73c7dd-0467-4e1b-a659-d5f180d66657', 'cfad9c1c-03ba-4f42-b6d3-772d11de7425', '871d184a-58a1-4f07-b344-a2c79efc0a94', 'The Little Lantern Adventure', 'https://picsum.photos/seed/story-cover-001/640/640', '871d184a-58a1-4f07-b344-a2c79efc0a94', 'Mia', '5-7', '{\"name\": \"Lantern Fox\", \"imageUrl\": \"https://picsum.photos/seed/character-001/400/400\", \"description\": \"A brave fox holding a glowing lantern\"}', '{\"name\": \"Moon Garden\", \"imageUrl\": \"https://picsum.photos/seed/place-001/400/400\", \"description\": \"A garden filled with silver flowers\"}', 'Moonlight Evening', '[{\"text\": \"Mia followed the lantern fox into the moon garden.\", \"imageUrl\": \"https://picsum.photos/seed/page-001/800/600\", \"imagePrompt\": \"Lantern fox entering a moon garden\"}, {\"text\": \"The flowers glowed brighter each time she told a kind story.\", \"imageUrl\": \"https://picsum.photos/seed/page-002/800/600\", \"imagePrompt\": \"Glowing flowers around a child storyteller\"}]', '{\"fontFamily\": \"font-comic\", \"titleColor\": \"#d97706\"}', 'published', '2026-03-24 20:25:54', '2026-03-24 20:25:54');
COMMIT;

-- ----------------------------
-- Table structure for students
-- ----------------------------
DROP TABLE IF EXISTS `students`;
CREATE TABLE `students` (
  `id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `school_id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `class_id` char(36) COLLATE utf8mb4_general_ci NOT NULL,
  `teacher_id` char(36) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `student_no` varchar(64) COLLATE utf8mb4_general_ci NOT NULL,
  `name` varchar(120) COLLATE utf8mb4_general_ci NOT NULL,
  `age_group` varchar(20) COLLATE utf8mb4_general_ci NOT NULL,
  `status` enum('active','disabled') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_student_no` (`student_no`),
  KEY `fk_students_school` (`school_id`),
  KEY `fk_students_class` (`class_id`),
  KEY `fk_students_teacher` (`teacher_id`),
  CONSTRAINT `fk_students_class` FOREIGN KEY (`class_id`) REFERENCES `classes` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_students_school` FOREIGN KEY (`school_id`) REFERENCES `schools` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_students_teacher` FOREIGN KEY (`teacher_id`) REFERENCES `teachers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- ----------------------------
-- Records of students
-- ----------------------------
BEGIN;
